
window.JSZip = class {
  constructor(){this._files=[];}
  file(name,data,opts={}){this._files.push({name,data,opts});return this;}
  async generateAsync(){
    const enc=new TextEncoder(), chunks=[], central=[]; let offset=0;
    const u16=n=>new Uint8Array([n&255,(n>>8)&255]);
    const u32=n=>new Uint8Array([n&255,(n>>8)&255,(n>>16)&255,(n>>24)&255]);
    const cat=arrs=>{let n=arrs.reduce((s,a)=>s+a.length,0),o=new Uint8Array(n),p=0;for(const a of arrs){o.set(a,p);p+=a.length}return o};
    const crcTable=(()=>{let t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
    const crc32=b=>{let c=0xffffffff;for(const x of b)c=crcTable[(c^x)&255]^(c>>>8);return (c^0xffffffff)>>>0};
    for(const f of this._files){
      let data;
      if(f.data instanceof Blob)data=new Uint8Array(await f.data.arrayBuffer());
      else if(f.data instanceof Uint8Array)data=f.data;
      else data=enc.encode(String(f.data));
      const name=enc.encode(f.name), crc=crc32(data), size=data.length;
      const local=cat([u32(0x04034b50),u16(20),u16(0),u16(0),u16(0),u16(0),u32(crc),u32(size),u32(size),u16(name.length),u16(0),name,data]);
      chunks.push(local);
      const cen=cat([u32(0x02014b50),u16(20),u16(20),u16(0),u16(0),u16(0),u16(0),u32(crc),u32(size),u32(size),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]);
      central.push(cen); offset+=local.length;
    }
    const centralBlob=cat(central), centralOffset=offset;
    chunks.push(centralBlob);
    chunks.push(cat([u32(0x06054b50),u16(0),u16(0),u16(this._files.length),u16(this._files.length),u32(centralBlob.length),u32(centralOffset),u16(0)]));
    return new Blob(chunks,{type:"application/zip"});
  }
};